const F=(a,b)=>`<span class="frac"><span>${a}</span><span>${b}</span></span>`;
const BS=['Benar','Salah'];

const MTK={ps:{},qs:[
{t:'kat',ctx:'<p>Bangun datar berikut merupakan potongan yang terlihat mewakili bagian dari suatu objek utuh.</p>',img:['m01a'],
 q:'Manakah dari gambar berikut ini yang merupakan gambar objek utuh tersebut?',cols:BS,rows:[{img:'m01b'},{img:'m01c'},{img:'m01d'}],ans:[0,1,0],
 exp:`<p>Potongan bernilai ${F(1,6)}, artinya objek utuh terdiri atas <b>6 bagian yang sama besar</b>, dan setiap bagian sama bentuk serta ukurannya dengan potongan (persegi panjang tegak).</p><ul><li><b>Gambar 1 – Benar.</b> Terdiri atas 6 persegi panjang yang sama besar (3 kolom × 2 baris).</li><li><b>Gambar 2 – Salah.</b> Ada 6 bagian, tetapi kolom tengah lebih sempit, jadi bagiannya tidak sama besar. Bagian yang sempit bukan ${F(1,6)}.</li><li><b>Gambar 3 – Benar.</b> Ada 6 persegi panjang yang sama dengan potongan, hanya disusun bertingkat. Susunan boleh berbeda asal ada 6 bagian yang sama.</li></ul>`},
{t:'pg',ctx:'<p>Tahukah kamu dari mana listrik berasal? Listrik berasal dari pembangkit listrik. Di Indonesia terdapat berbagai macam pembangkit listrik. Pembangkit listrik tersebut telah menghasilkan tenaga listrik sebanyak 40.000 megawatt. Berikut kapasitas listrik yang dihasilkan dari setiap pembangkit listrik.</p>',img:['m02'],
 q:'Jenis pembangkit listrik yang menghasilkan listrik terbesar adalah ....',opts:['PLTA','PLTG','PLTU','PLTGU'],ans:2,
 exp:`<p>Samakan dulu semua bentuk bilangan menjadi persen:</p><ul><li>PLTU = ${F(1,2)} = 50%</li><li>PLTA = 0,075 = 7,5%</li><li>PLTG = 5%</li><li>PLTGU = 30%</li><li>PLTD = ${F(3,40)} = 7,5%</li></ul><p>Yang terbesar adalah <b>PLTU (50%)</b>, yaitu 50% × 40.000 = 20.000 megawatt.</p>`},
{t:'mcma',ctx:'<p>Pemerintah suatu desa membuat program untuk memenuhi kebutuhan pokok warganya. Pemerintah desa tersebut akan memberikan bantuan berupa beras kepada keluarga kurang mampu. Sebelum dibagikan, beras dimasukkan ke dalam karung-karung dengan ukuran yang sama. Pemerintah desa hanya dapat menggunakan salah satu jenis karung berikut.</p>',img:['m03'],
 q:'Pada bulan Januari 2024, terdapat 150 karung beras yang akan dibagikan. Setiap keluarga memperoleh beras dengan jumlah yang sama dan dapat menerima lebih dari satu karung. Berapa banyak keluarga kurang mampu yang mungkin akan menerima beras pada bulan Januari 2024?',opts:['30','25','20'],ans:[0,1],
 exp:`<p>150 karung harus dibagi sama rata dan karungnya utuh (tidak dibongkar), jadi banyak keluarga harus merupakan <b>faktor dari 150</b>.</p><ul><li>150 : 30 = 5 karung per keluarga → <b>bisa</b>.</li><li>150 : 25 = 6 karung per keluarga → <b>bisa</b>.</li><li>150 : 20 = 7,5 karung → tidak bisa, karena karung tidak dibagi setengah.</li></ul>`},
{t:'pg',ctx:'<p>(Masih tentang bantuan beras dan dua jenis karung di atas.)</p>',img:['m03'],
 q:'Pada bulan Juli 2024, pemerintah hanya memiliki persediaan beras sebanyak 1.500 kg. Keseluruhan beras dikemas dalam karung jenis B, dan setiap keluarga kurang mampu (450 keluarga) mendapat satu karung. Setelah semua keluarga memperoleh bantuan, berapa karung beras yang tersisa?',opts:['500 karung.','300 karung.','150 karung.','50 karung.'],ans:3,
 exp:`<p>Karung jenis B berisi 3 kg.</p><ul><li>Banyak karung = 1.500 : 3 = 500 karung.</li><li>Dibagikan ke 450 keluarga, masing-masing 1 karung = 450 karung.</li><li>Sisa = 500 − 450 = <b>50 karung</b>.</li></ul>`},
{t:'pg',ctx:'<p>Sebuah pabrik <i>home industry</i> memproduksi keripik kentang. Kentang mentah disimpan dalam karung sebagai berikut.</p>',img:['m05'],
 q:'Dari satu karung kentang telah dibuat sejumlah keripik dan masih tersisa 4 kg. Setiap 1 kg kentang dapat dibuat menjadi 6 bungkus keripik. Setiap kardus dapat memuat 12 bungkus keripik. Perhitungan yang tepat untuk menentukan banyak kardus yang dibutuhkan adalah ....',
 opts:['(100 − 4) × 6 : 12','(100 − 4) : 6 × 12','(100 + 4) × 6 : 12','(100 + 4) : 6 × 12'],ans:0,
 exp:`<ul><li>Kentang yang dipakai = 100 − 4 = 96 kg (sisa 4 kg <b>dikurangi</b>).</li><li>Banyak bungkus = 96 × 6 = 576 bungkus (1 kg jadi 6 bungkus, maka <b>dikali</b> 6).</li><li>Banyak kardus = 576 : 12 = 48 kardus (1 kardus memuat 12 bungkus, maka <b>dibagi</b> 12).</li></ul><p>Kalimat matematikanya: <b>(100 − 4) × 6 : 12</b>.</p>`},
{t:'pg',q:`Hasil dari ${F(3,25)} × 3${F(7,6)} + 135 : 15 adalah ....`,opts:[`2${F(1,2)}`,`9${F(1,30)}`,`9${F(1,2)}`,F(32,225)],ans:2,
 exp:`<p>Kerjakan perkalian dan pembagian lebih dulu, baru penjumlahan.</p><ul><li>3${F(7,6)} = ${F('18 + 7',6)} = ${F(25,6)}</li><li>${F(3,25)} × ${F(25,6)} = ${F(75,150)} = ${F(1,2)}</li><li>135 : 15 = 9</li><li>${F(1,2)} + 9 = <b>9${F(1,2)}</b></li></ul>`},
{t:'kat',ctx:'<p>Sebuah program memiliki proses berpikir sebagai berikut:</p>',img:['m07'],q:'Tentukan Benar atau Salah pada setiap pernyataan berikut berdasarkan program tersebut!',cols:BS,
 rows:['Jika bilangan yang dimasukkan adalah bilangan ganjil, maka hasil akhir juga bilangan ganjil.','Hasil akhir adalah nol jika bilangan yang dimasukkan adalah bilangan 0.','Jika bilangan yang dimasukkan adalah bilangan genap, maka hasil akhir adalah bilangan kelipatan dua.'],ans:[1,0,0],
 exp:`<p>Langkah terakhir program selalu <b>“kalikan dengan 2”</b>, sehingga hasil akhir selalu bilangan genap (kelipatan 2).</p><ul><li><b>Pernyataan 1 – Salah.</b> Contoh: masukkan 1 → 1 + 5 = 6 (kelipatan 6) → 6 : 3 = 2 → 2 × 2 = 4 (genap). Masukkan 3 → 8 (bukan kelipatan 6) → 8 − 5 = 3 → 3 × 2 = 6 (genap).</li><li><b>Pernyataan 2 – Benar.</b> 0 + 5 = 5 (bukan kelipatan 6) → 5 − 5 = 0 → 0 × 2 = 0.</li><li><b>Pernyataan 3 – Benar.</b> Contoh: 4 → 9 → 9 − 5 = 4 → 8. Apa pun masukannya, hasil dikali 2 sehingga pasti kelipatan dua.</li></ul>`},
{t:'pg',ctx:'<p>Tahukah kamu bahwa tidak semua benda dapat ditarik magnet?</p><p>Feromagnetik adalah benda yang mudah ditarik magnet. Paramagnetik adalah benda yang lemah ditarik magnet. Diamagnetik adalah benda yang sulit ditarik magnet.</p>',img:['m08'],
 q:'Di dalam suatu wadah terdapat 25 benda. Ternyata 12 di antaranya feromagnetik dan 7 lainnya paramagnetik. Sisanya adalah benda diamagnetik. Setelah itu, benda tersebut ditambah sehingga menjadi 9 benda diamagnetik. Berapakah benda diamagnetik yang baru ditambahkan?',opts:['3 benda.','5 benda.','9 benda.','15 benda.'],ans:0,
 exp:`<ul><li>Diamagnetik mula-mula = 25 − 12 − 7 = 6 benda.</li><li>6 + □ = 9 → □ = 9 − 6 = <b>3 benda</b>.</li></ul>`},
{t:'mcma',ctx:'<p>Di suatu desa terdapat tiga kincir air, yaitu kincir A, B, dan C. Besar daya listrik yang dihasilkan masing-masing kincir <b>setiap harinya</b> dapat dilihat pada gambar berikut.</p>',img:['m09'],
 q:'Ketiga kincir digunakan selama dua hari. Sisa daya listrik dari kincir A 42 watt, kincir B 13 watt, dan kincir C 30 watt. Daya listrik dari kincir mana saja yang telah digunakan warga desa lebih dari 150 watt?',opts:['Kincir A','Kincir B','Kincir C'],ans:[1,2],
 exp:`<p>Daya 2 hari = daya per hari × 2. Daya terpakai = daya 2 hari − sisa.</p><ul><li>Kincir A: 94 × 2 = 188 → 188 − 42 = 146 watt (tidak lebih dari 150).</li><li>Kincir B: 82 × 2 = 164 → 164 − 13 = <b>151 watt</b> ✓</li><li>Kincir C: 96 × 2 = 192 → 192 − 30 = <b>162 watt</b> ✓</li></ul>`},
{t:'pg',ctx:'<p>Ikan salmon merupakan salah satu ikan yang memiliki banyak kandungan bergizi. Berikut ini informasi terkait manfaat mengonsumsi ikan salmon.</p>',img:['m10'],
 q:'Jika dalam satu sajian ikan salmon terdapat 80 gram protein, berapa porsi salmon yang disajikan dalam sajian tersebut?',opts:['8 porsi.','6 porsi.','4 porsi.','2 porsi.'],ans:2,
 exp:`<p>Dari infografis, satu porsi salmon mengandung sekitar <b>20 gram protein</b>.</p><p>Banyak porsi = 80 : 20 = <b>4 porsi</b>. (Hati-hati, angka 10 gram itu kandungan lemak omega-3, bukan protein.)</p>`},
{t:'kat',ctx:'<p>Keju dibuat melalui proses koagulasi (pengentalan susu sapi segar) lalu flokulasi (penggumpalan protein). Proses pembuatan keju sederhana dapat dilakukan sendiri dengan bahan-bahan berikut.</p>',img:['m11a','m11b'],
 q:'Setiap satu resep dibutuhkan garam sebanyak 4 gr. Seseorang akan membuat keju sebanyak 5 kali resep awal. Persediaan bahannya adalah 2.000 ml susu sapi segar, 140 ml cuka, dan 16 gr garam. Apakah bahan yang tersedia cukup?',cols:BS,
 rows:['Seharusnya disediakan garam sebanyak 20 gr.','Terdapat kekurangan cuka sebanyak 40 ml.','Tidak perlu tambahan susu sapi segar.'],ans:[0,1,0],
 exp:`<p>Satu resep: susu 2 gelas = 2 × 200 = 400 ml; cuka 4 sendok teh = 4 × 5 = 20 ml; garam 4 gr. Untuk 5 resep:</p><ul><li>Garam = 5 × 4 = <b>20 gr</b> → pernyataan 1 <b>Benar</b> (persediaan 16 gr kurang 4 gr).</li><li>Cuka = 5 × 20 = 100 ml. Persediaan 140 ml, jadi <b>lebih</b> 40 ml, bukan kurang → pernyataan 2 <b>Salah</b>.</li><li>Susu = 5 × 400 = 2.000 ml, sama dengan persediaan → pernyataan 3 <b>Benar</b>.</li></ul>`},
{t:'mcma',ctx:'<p><b>Laundry Koin.</b> Linda dan Vidya mencuci baju di tempat <i>laundry</i> koin yang sama. Jadwal mereka berbeda, tetapi jam kedatangannya sama, sekitar pukul 16.00. Perhatikan gambar berikut.</p>',img:['m12'],
 q:'Pada tanggal 10 Agustus 2024, Linda dan Vidya bertemu di tempat <i>laundry</i> tersebut. Kapankah mereka akan bertemu kembali?',opts:['3 September 2024','27 September 2024','21 Oktober 2024'],ans:[0,1,2],
 exp:`<p>Linda datang tiap 8 hari, Vidya tiap 6 hari. Mereka bertemu lagi setiap <b>KPK(8, 6) = 24 hari</b>.</p><ul><li>10 Agustus + 24 hari → Agustus punya 31 hari, sisa Agustus 21 hari, lalu 3 hari lagi = <b>3 September</b>.</li><li>3 September + 24 hari = <b>27 September</b>.</li><li>27 September + 24 hari → sisa September 3 hari, lalu 21 hari lagi = <b>21 Oktober</b>.</li></ul><p>Ketiga tanggal semuanya benar.</p>`},
{t:'kat',ctx:'<p>Perajin kayu sedang membuat hiasan dinding berbentuk huruf berikut. Bentuk huruf tersebut dianggap menjadi satu bidang datar.</p>',img:['m13'],q:'Bagaimanakah ciri-ciri hiasan dinding tersebut?',cols:BS,
 rows:['Memiliki 12 sisi.','Terdapat 12 titik sudut.','Terdapat 10 sudut siku-siku.'],ans:[0,0,1],
 exp:`<p>Telusuri tepi huruf E: atas (1), tepi kanan lengan atas (2), bawah lengan atas (3), tegak dalam (4), atas lengan tengah (5), ujung lengan tengah (6), bawah lengan tengah (7), tegak dalam (8), atas lengan bawah (9), ujung lengan bawah (10), bawah (11), punggung kiri (12).</p><ul><li><b>12 sisi – Benar</b>, dan setiap sisi bertemu di satu titik sudut, jadi <b>12 titik sudut – Benar</b>.</li><li><b>10 sudut siku-siku – Salah.</b> Dari 12 sudut, 4 sudut berada di lekukan dalam (tempat lengan menempel ke punggung huruf). Sudut dalamnya 270° (sudut refleks), bukan siku-siku. Jadi sudut siku-sikunya hanya 12 − 4 = <b>8</b>.</li></ul>`},
{t:'kat',ctx:'<p>Gambar berikut memperlihatkan sebuah segi banyak yang dibentuk dari gabungan beberapa bangun datar tanpa beririsan.</p>',img:['m14'],q:'Berikut ini adalah pernyataan banyak segitiga dan segiempat yang menyusun segi banyak tersebut.',cols:BS,
 rows:['3 segitiga dan 1 persegi panjang.','4 segitiga dan 1 trapesium.','5 segitiga dan 1 layang-layang.'],ans:[0,0,0],
 exp:`<p>Bagian tengah bangun adalah sebuah persegi panjang, dengan tiga segitiga yang menempel (atas-kiri, kanan, dan bawah). Satu bangun bisa dipotong dengan beberapa cara:</p><ul><li><b>Benar</b> – 3 segitiga + 1 persegi panjang: cara paling langsung.</li><li><b>Benar</b> – 4 segitiga + 1 trapesium: potong satu ujung persegi panjang secara miring, jadi persegi panjang terbagi menjadi 1 segitiga siku-siku + 1 trapesium.</li><li><b>Benar</b> – 5 segitiga + 1 layang-layang: segitiga kanan digabung dengan segitiga cerminannya di dalam persegi panjang sehingga membentuk layang-layang. Sisa persegi panjang dipotong menjadi 3 segitiga. Jumlahnya 2 (atas, bawah) + 3 = 5 segitiga.</li></ul><p><i>Catatan: soal ini menguji kemungkinan susunan, jadi ketiga cara bisa diterima.</i></p>`},
{t:'pg',ctx:'<p>Gambar berikut memperlihatkan susunan kubus berukuran sama.</p>',img:['m15'],q:'Berdasarkan gambar tersebut, jumlah semua kubus yang mungkin adalah ....',opts:['12','13','14','15'],ans:3,
 exp:`<p>Hitung per lapis.</p><ul><li><b>Lapis bawah (terlihat):</b> 7 kubus (2 di kiri-depan, 1 di depan tengah, 1 di belakangnya, 1 di belakang kanan, 2 di kanan).</li><li><b>Lapis bawah (tersembunyi):</b> 2 kubus penyangga, yaitu di bawah menara dan di bawah kubus belakang yang “mengambang” setinggi 2. Kubus tidak bisa melayang, jadi pasti ada.</li><li><b>Kubus di atas lapis bawah:</b> 1 (tumpukan kiri) + 4 (menara) + 1 (kubus belakang) = 6.</li></ul><p>Jumlah = 7 + 2 + 6 = <b>15 kubus</b>.</p>`},
{t:'mcma',q:'Berikut ini, manakah yang menunjukkan hasil pengukuran yang paling tepat dan masuk akal?',opts:['Tinggi tiang bendera di sekolah adalah 8 meter.','Jarak rumah Budi ke sekolah adalah 30 milimeter.','Lebar buku tulis ini sekitar 20 centimeter.'],ans:[0,2],
 exp:`<ul><li><b>Tiang bendera 8 m – masuk akal.</b> Tiang bendera sekolah umumnya 6–10 m.</li><li><b>Jarak rumah 30 mm – tidak masuk akal.</b> 30 mm = 3 cm, sepanjang ruas jari. Jarak rumah ke sekolah mestinya memakai meter atau kilometer.</li><li><b>Lebar buku tulis 20 cm – masuk akal.</b> Buku tulis umumnya selebar ±16–21 cm.</li></ul>`},
{t:'pg',ctx:'<p>Dewi dan temannya bermain air warna-warni dalam botol. Ukuran dan bentuk botolnya sama. Botol A diisi air merah 450 ml, botol B air hijau 530 ml, botol C air kuning 540 ml, dan botol D air biru 470 ml.</p>',
 q:'Manakah gambar yang tepat menunjukkan tinggi permukaan air berwarna di setiap botol?',opts:[{img:'m17a'},{img:'m17b'},{img:'m17c'},{img:'m17d'}],ans:1,
 exp:`<p>Botolnya sama, jadi makin banyak air, makin tinggi permukaannya. Urutan dari terendah: <b>A (450) &lt; D (470) &lt; B (530) &lt; C (540)</b>. A dan D hampir sama rendah, sedangkan B dan C hampir sama tinggi dengan C sedikit lebih tinggi.</p><ul><li>Gambar A: D lebih rendah dari A → salah.</li><li><b>Gambar B: A paling rendah, D sedikit di atasnya, B tinggi, C paling tinggi → benar.</b></li><li>Gambar C: C lebih rendah dari B → salah.</li><li>Gambar D: A paling tinggi dan C rendah → salah.</li></ul>`},
{t:'kat',ctx:'<p>Bu Halimah berjualan cireng isi ayam suwir pedas. Bahan-bahan yang ia gunakan adalah sebagai berikut.</p>',img:['m18'],q:'Bagaimana hubungan berat bahan-bahan tersebut jika ditimbang menggunakan neraca?',cols:BS,
 rows:[{img:'m18a'},{img:'m18b'},{img:'m18c'}],ans:[0,1,0],
 exp:`<p>Pada neraca, sisi yang lebih berat akan <b>turun</b>. Jika beratnya sama, neraca seimbang.</p><ul><li><b>Gambar 1 – Benar.</b> Bawang putih 250 g = cabai 250 g → seimbang.</li><li><b>Gambar 2 – Salah.</b> Tepung bungkus biru 500 g lebih ringan dari ayam 1.500 g, jadi sisi ayam yang harus turun. Di gambar justru sisi tepung yang turun.</li><li><b>Gambar 3 – Benar.</b> Tepung tapioka 1.250 g lebih berat dari tepung bungkus biru 500 g, jadi sisi tapioka turun.</li></ul>`},
{t:'pg',ctx:'<p>Bu Nina memasak beberapa jenis makanan untuk keluarganya. Waktu memulai dan selesai memasak ditunjukkan seperti pada gambar jam berikut ini.</p>',img:['m19'],q:'Berapa lama Bu Nina memasak makanan tersebut?',opts:['2 jam 10 menit.','2 jam 40 menit.','3 jam 10 menit.','3 jam 40 menit.'],ans:0,
 exp:`<ul><li>Mulai: jarum panjang di angka 3 (15 menit), jarum pendek baru lewat angka 8 → <b>08.15</b>.</li><li>Selesai: jarum panjang di angka 5 (25 menit), jarum pendek di antara 10 dan 11 → <b>10.25</b>.</li><li>Lama = 10.25 − 08.15 = <b>2 jam 10 menit</b>.</li></ul>`},
{t:'pg',ctx:'<p>Gambar berikut menunjukkan sketsa bangun datar beserta ukurannya.</p>',img:['m20'],q:'Keliling bangun tersebut adalah ....',opts:['46 cm','50 cm','56 cm','60 cm'],ans:3,
 exp:`<p>Tanda garis kecil yang sama berarti panjang sisinya sama. Dua sisi miring bertanda satu garis = 10 cm. Dua sisi tegak bertanda dua garis = 4 cm.</p><p>Keliling = 12 + 10 + 10 + 4 + 4 + 20 = <b>60 cm</b>.</p>`},
{t:'pg',ctx:'<p>Segi banyak tersebut tersusun dari beberapa segitiga yang berukuran sama. Gambar berikut ini memperlihatkan kenampakan bangun segi banyak tersebut.</p>',img:['m21'],q:'Berapakah luas segi banyak tersebut?',opts:['176 cm²','160 cm²','144 cm²','128 cm²'],ans:1,
 exp:`<p>Hitung berapa segitiga (sama dengan segitiga cokelat) yang menyusun bangun.</p><ul><li>Pita tengah berbentuk jajar genjang yang panjangnya 4 kali alas segitiga. Isinya 4 segitiga menghadap atas + 4 segitiga menghadap bawah = 8 segitiga.</li><li>Segitiga yang menonjol ke atas = 1, yang menonjol ke bawah = 1.</li></ul><p>Total 10 segitiga × 16 cm² = <b>160 cm²</b>.</p>`},
{t:'pg',ctx:'<p>Jimmi diajak orang tuanya melihat pameran lukisan. Ia tertarik pada satu dinding yang memajang 5 lukisan bertema binatang seperti pada gambar.</p>',img:['m22'],
 q:'Jimmi ingin membeli lukisan untuk dipajang di rumahnya. Ia menyediakan tempat di kamarnya dengan luas 4.800 cm². Lukisan manakah yang bisa dipajang Jimmi?',opts:['Lukisan A dan Lukisan B','Lukisan C dan Lukisan D','Lukisan E dan A','Lukisan B dan Lukisan D'],ans:1,
 exp:`<p>Luas tiap lukisan (panjang × lebar):</p><ul><li>A: 60 × 60 = 3.600 cm²</li><li>B: 90 × 80 = 7.200 cm²</li><li>C: 40 × 80 = 3.200 cm²</li><li>D: 40 × 40 = 1.600 cm²</li><li>E: 60 × 80 = 4.800 cm²</li></ul><p>Gabungan yang muat di 4.800 cm²: <b>C + D = 3.200 + 1.600 = 4.800 cm²</b>. Pilihan lain melebihi tempat: A + B = 10.800, E + A = 8.400, B + D = 8.800.</p>`},
{t:'pg',ctx:'<p>Desa Makmur terkenal sebagai pembuat kerajinan dari kain perca (kain sisa produksi konveksi). Salah satu produknya adalah keset. Berikut bentuk, ukuran, dan berat tiap jenis keset.</p>',img:['m23'],
 q:'Suatu hari terdapat pesanan keset jenis 2 yang diberi hiasan pada setiap sudutnya. Berapa banyak hiasan yang ada pada satu keset tersebut?',opts:['2 hiasan','4 hiasan','5 hiasan','6 hiasan'],ans:1,
 exp:`<p>Keset jenis 2 berbentuk <b>persegi panjang</b> (panjang 60 cm, lebar 40 cm). Persegi panjang memiliki <b>4 titik sudut</b>, jadi hiasannya <b>4 buah</b>.</p>`},
{t:'kat',ctx:'<p>(Masih tentang keset Desa Makmur.) Jenis 1: 800 gram. Jenis 2: 1.200 gram. Jenis 3: 1.500 gram.</p>',img:['m23'],
 q:'Keset dikemas dalam kardus. Di dalam satu kardus ada dua jenis keset yang berbeda. Banyak keset pada setiap kardus akan dimaksimalkan, tetapi total berat tidak boleh melebihi 10 kg. Berapa banyak keset yang sebaiknya dimasukkan ke dalam kardus?',cols:BS,
 rows:['12 buah keset.','7 buah keset.','6 buah keset.'],ans:[0,1,1],
 exp:`<p>Agar jumlahnya paling banyak, pakai sebanyak mungkin keset yang <b>paling ringan</b> (jenis 1 = 0,8 kg), ditambah minimal 1 keset jenis lain yang paling ringan berikutnya (jenis 2 = 1,2 kg).</p><ul><li>10 kg − 1,2 kg = 8,8 kg → 8,8 : 0,8 = 11 keset jenis 1.</li><li>Total = 11 + 1 = <b>12 keset</b>, beratnya tepat 8,8 + 1,2 = 10 kg ✓</li></ul><p>7 dan 6 keset memang tidak melebihi 10 kg, tetapi <b>belum maksimal</b>, jadi Salah.</p>`},
{t:'mcma',ctx:'<p>Dua buah gunting terbuka sehingga masing-masing membentuk sudut seperti tampak pada gambar berikut.</p>',img:['m25'],q:'Berapa sudut yang mungkin dibentuk oleh gunting B?',opts:['29°','51°','63°'],ans:[1,2],
 exp:`<p>Gunting B terbuka <b>lebih lebar</b> daripada gunting A (35°), tetapi bukaannya belum mencapai siku-siku (90°). Jadi sudut B berada di antara 35° dan 90°.</p><ul><li>29° → lebih kecil dari 35° → tidak mungkin.</li><li><b>51°</b> dan <b>63°</b> → di antara 35° dan 90° → mungkin.</li></ul>`},
{t:'pg',ctx:'<p>Pengusaha UMKM merintis usaha roti di dua cabang, Jakarta dan Tangerang. Berikut data produksi rotinya. Sumbu x menyatakan bulan produksi, sumbu y menyatakan jumlah roti.</p>',img:['m26j','m26t'],
 q:'Berdasarkan informasi yang diberikan, manakah gabungan produksi roti yang tepat dari dua cabang tersebut?',opts:[{img:'m26a'},{img:'m26b'},{img:'m26c'},{img:'m26d'}],ans:2,
 exp:`<p>Jumlahkan produksi per bulan (Jakarta + Tangerang):</p><ul><li>Januari: 500 + 500 = 1.000</li><li>Februari: 1.000 + 500 = 1.500</li><li>Maret: 750 + 1.500 = 2.250</li><li>April: ±1.200 + 2.000 = ±3.200 (di atas 3.000)</li><li>Mei: 1.500 + 2.500 = 4.000</li></ul><p>Yang cocok adalah <b>grafik C</b>. Grafik A salah di Maret (±2.100), grafik B salah di April (tepat 3.000), dan grafik D salah di Mei (3.000, padahal seharusnya 4.000).</p>`},
{t:'mcma',ctx:'<p><i>Screen time</i> adalah waktu yang dihabiskan untuk menonton TV, memakai komputer/laptop, bermain <i>game</i>, <i>handphone</i>, dan sejenisnya. Batas <i>screen time</i> Siska adalah 2 jam pada hari sekolah dan 2,5 jam pada hari libur. Berikut laporan Siska kepada sekolah.</p>',img:['m27'],
 q:'Siska sudah melewati batas <i>screen time</i>. Tentukan pengurangan waktu total <i>screen time</i> yang dapat dilakukan oleh Siska pada hari sekolah!',opts:['6 jam','5 jam','4 jam'],ans:[0,1],
 exp:`<p>Baca batang biru (hari sekolah): TV 1 + Komputer 0,5 + Laptop 1 + Game 2,5 + HP 2 = <b>7 jam</b>.</p><p>Batasnya 2 jam, jadi Siska harus mengurangi <b>paling sedikit 7 − 2 = 5 jam</b>.</p><ul><li>Dikurangi 6 jam → sisa 1 jam (≤ 2) ✓</li><li>Dikurangi 5 jam → sisa 2 jam (= batas) ✓</li><li>Dikurangi 4 jam → sisa 3 jam (masih lewat batas) ✗</li></ul>`},
{t:'pg',ctx:'<p>Pak Fajar, pengurus kantin sekolah, selalu mendata jumlah menu yang terjual setiap hari. Berikut penjualan hari Kamis.</p>',img:['m28'],q:'Berapa banyak murid yang membeli telur gulung?',opts:['22','23','24','25'],ans:1,
 exp:`<p>Batang telur gulung berhenti di antara garis 22 dan 24, tepat di tengahnya → <b>23 murid</b>. (Batang yang mencapai 24 adalah es teh.)</p>`},
{t:'kat',ctx:'<p>Panas bumi dari gunung berapi bisa menjadi pembangkit listrik. Berikut data gunung berapi yang masih aktif di beberapa negara (1960–2023).</p>',img:['m29'],
 q:'Peneliti mengatakan bahwa dengan jumlah gunung berapi yang ada di Tonga, negara tersebut dapat menghasilkan paling sedikit 450 Mw listrik. Bila setiap gunung api aktif diasumsikan menghasilkan energi yang sama, berapakah energi listrik yang dihasilkan negara lainnya?',cols:BS,
 rows:['Gunung berapi di Rusia dapat menghasilkan paling sedikit 1.350 Mw listrik.','Gunung berapi di Vanuatu dapat menghasilkan paling sedikit 450 Mw listrik.','Gunung berapi di Papua Nugini dapat menghasilkan paling sedikit 550 Mw listrik.'],ans:[0,0,1],
 exp:`<p>Tonga punya 9 gunung api → 450 : 9 = <b>50 Mw per gunung</b>.</p><ul><li>Rusia 27 gunung × 50 = 1.350 Mw → <b>Benar</b>.</li><li>Vanuatu 9 gunung × 50 = 450 Mw → <b>Benar</b>.</li><li>Papua Nugini ±13 gunung × 50 = 650 Mw, bukan 550 Mw (550 Mw berarti 11 gunung) → <b>Salah</b>.</li></ul>`},
{t:'pg',ctx:'<p><b>Karya Wisata.</b> SD Pelita mengadakan karya wisata ke Monas. Pak Amir mendata jumlah siswa kelas 6 yang ikut.</p>',img:['m30'],
 q:'Seluruh siswa kelas 6 menempati 1 bus yang menampung paling banyak 72 siswa. Diketahui tidak ada kursi tersisa. Berapa banyak siswa kelas 6C yang mengikuti karya wisata?',opts:['22 siswa.','23 siswa.','24 siswa.','25 siswa.'],ans:1,
 exp:`<ul><li>Dari diagram: kelas 6A = 25 siswa, kelas 6B = 24 siswa.</li><li>Bus penuh (tidak ada kursi tersisa), jadi total = 72.</li><li>6C = 72 − 25 − 24 = <b>23 siswa</b>.</li></ul>`}
]};

const BIN={ps:{
mangrove:{title:'Indahnya Hutan-Hutan Mangrove di Indonesia',html:`<p>Hutan Mangrove di Kulon Progo, Yogyakarta adalah tempat yang menyuguhkan keindahan alam menyejukkan hati. Hutan ini terletak di dekat Pantai Congot, kawasan ini terbagi menjadi beberapa zona menarik seperti Pasir Mendit, Jembatan Api-Api, dan Pantai Kadilangu. Luasnya mencapai sekitar tiga kilometer persegi, dipenuhi pohon-pohon bakau dengan akar unik yang menjulur di atas air.</p><p>Begitu melangkah ke dalam area, pengunjung akan disambut oleh jembatan kayu dan suasana rindang yang membuat hati tenang. Banyak spot foto menarik seperti ayunan, gazebo, dan menara pandang. Tak heran jika tempat ini disebut sebagai "permata tersembunyi" di Kulon Progo.</p><p>Selain indah, hutan ini juga menjadi rumah bagi beragam satwa seperti burung kuntul, kepiting, udang, dan biawak kecil. Ada jalur kayu yang bisa dilewati sambil menikmati semilir angin pantai. Jika ingin lebih dekat dengan alam, pengunjung juga bisa naik perahu menyusuri rimbunnya hutan.</p><p>Hutan Mangrove Kulon Progo bukan hanya indah dipandang mata, tapi juga punya peran penting bagi lingkungan. Tempat ini ibarat "paru-paru kecil" pesisir yang menjaga alam tetap seimbang sekaligus menjadi lokasi belajar mencintai alam sejak dini.</p>`,src:'Sumber: kompas.com, detik.com, kompasiana.com'},
bakwan:{img:['b07'],html:`<p>Bakwan merupakan makanan unik yang banyak disukai. Bakwan muncul karena pengaruh dari berbagai budaya, seperti Cina, Jepang, bahkan Eropa (Portugis).</p><p>Awalnya, bakwan terbuat dari daging dan tepung yang digoreng. Di Jepang, sayur yang digoreng tepung disebut "tempura". Makanan tersebut bisa jadi ikut memengaruhi berkembangnya bakwan di Indonesia.</p><p>Kini, bakwan berisi aneka sayuran, seperti taoge, kol, dan wortel, yang dicampur dengan adonan tepung berbumbu rempah. Bisa juga ditambahkan isian udang, sosis, atau bakso.</p><p>Nama bakwan berbeda di tiap daerah. Jakarta, Yogyakarta, Manado, dan Lampung menyebutnya bakwan. Di banyak kota di Jawa Timur disebut ote-ote atau weci. Di Bandung disebut bala-bala. Sementara, di Semarang dan Pekalongan disebut badak.</p>`,src:'Terinspirasi dari tulisan di idntimes.com dan rri.co.id'},
biru:{title:'Si Biru Kesayangan',html:`<div class="dlg"><p><i>Salma, Alvin, dan Siva sedang menikmati waktu istirahat.</i></p><p><b>Salma:</b> (memeluk botol minumnya) "Minum dulu, ah! Botolku ini hadiah dari Ibu waktu ulang tahun. Aku beri nama dia Si Biru."</p><p><b>Alvin:</b> "Hah? Botol aja dikasih nama? Aneh banget, Sal!"</p><p><b>Siva:</b> "Ih, botol minum Salma lucu banget. Kamu tiap hari bawa Si Biru, ya?"</p><p><b>Salma:</b> "Iya, dong. Si Biru sudah menemani aku setahun ini. Aku jadi nggak pernah beli minuman kemasan lagi!"</p><p><b>Alvin:</b> "Ah, ribet. Aku sih, tinggal beli aja. Kalau sudah habis tinggal buang." (mengejek Salma)</p><p><b>Salma:</b> "Vin, tahu, nggak? Plastik yang kamu buang itu bisa jadi sampah lingkungan bertahun-tahun. Bisa mencemari tanah dan air juga, lho."</p><p><b>Siva:</b> "Benar, Vin. Aku juga sekarang bawa botol. Nih, gambar dinosaurus!"</p><p><b>Salma:</b> "Kita nggak bisa terus tutup mata soal sampah plastik. Kita harus peduli. Mulai dari hal kecil, seperti bawa botol sendiri."</p><p><b>Alvin:</b> "Hmm, kalau aku punya botol keren, mungkin aku jadi ingin bawa botol."</p><p><b>Salma:</b> "Benar sekali. Kita bantu cari botol yang cocok buat kamu, deh."</p><p><b>Alvin:</b> "Oke, setuju! Aku mau botol warna oranye, biar beda dari yang lain!"</p><p><b>Siva:</b> "Siap, nanti kita cari bersama, ya!"</p></div>`},
meteor:{img:['b12'],html:`<p><i>Buku harianku,</i></p><p>Ayah akan mengajakku melihat hujan meteor. Meteor adalah batu atau debu antarplanet. Ketika meteor jatuh ke bumi, meteor terbakar karena gesekan lapisan udara bumi. Itu sebabnya, meteor terlihat seperti bintang jatuh atau bintang berpindah.</p><p>Aku berdoa supaya hari itu tidak hujan. Meteor tampak lebih jelas jika langit cerah. Jika aku beruntung, aku dapat melihat belasan meteor per jam.</p><p>Awalnya aku khawatir kalau bintang jatuh dapat menimpaku. Untunglah, ayah sudah menenangkanku. Hujan meteor tidak berbahaya, kok. Jangan takut, meteor ini akan habis terbakar di langit.</p><p>Duh, rasanya tidak sabar. Aku senang sekali menghabiskan waktu dengan ayah!</p>`,src:'Referensi: brin.go.id, dengan perubahan. Ilustrasi oleh Sonny.'},
giga:{title:'Giga si Segitiga',html:`<p>Giga si Segitiga mempunyai banyak ide. Dia senang menirukan bentuk. Dia sering mengajak teman-temannya bermain bersama.</p><p>Banyak bentuk yang bisa ditiru. Bentuk dan sudut yang sama membuat mereka selalu serasi. Contohnya pohon cemara, gunung, atap rumah, bendera, dan kipas angin.</p><img src="img/b14a.jpg" alt="" loading="lazy"><p>Giga juga suka bermain dengan Pasukan Kotak. Banyak bentuk yang bisa ditirukan, seperti roket, ikan, dan menara.</p><img src="img/b14b.jpg" alt="" loading="lazy"><p>Saat bermain dengan Heksagonal, dia menirukan bentuk bunga.</p><img src="img/b15.jpg" alt="" loading="lazy"><p>Bentuk mereka memang berbeda. Namun, mereka memiliki sudut-sudut yang pas.</p><p>Giga sedih Lingkaran tak mau bermain dengannya. Lingkaran takut pada sudut-sudut tajam milik Giga. Padahal, Giga bisa berhati-hati. Giga juga sudah membayangkan bentuk-bentuk yang bisa dibuat.</p>`},
capgomeh:{img:['b18'],title:'Cap Go Meh di Pulau Kemaro',html:`<p><i>Oleh: Avyubie Cantika Yuranda</i></p><p>Adit dan Danu senang sekali hari ini karena Ibu dan Ayah akan mengajak mereka pergi melihat perayaan Cap Go Meh di Pulau Kemaro. Masyarakat Tionghoa di Kota Palembang merayakan Cap Go Meh, dan orang tuanya ingin mengenalkan perayaan tersebut kepada mereka.</p><p>Ini adalah kedua kalinya Adit dan Danu pergi ke Pulau Kemaro. Waktu itu, mereka naik kapal dari bawah jembatan Musi. Kali ini, mereka akan menyeberangi sungai Musi dengan berjalan kaki di atas jembatan ponton, yang dipasang khusus saat perayaan Imlek setiap tahunnya. Mereka berangkat setelah makan malam.</p><p>Malam itu, banyak orang berjalan kaki melewati jembatan ponton ke Pulau Kemaro. Semua orang memakai baju merah, termasuk keluarga Adit dan Danu. Di Pulau Kemaro, mereka menyaksikan pertunjukan barongsai dan penerbangan lampion. Acaranya sangat meriah. Adit dan Danu senang bisa mengenal kebudayaan Tionghoa melalui perayaan Cap Go Meh.</p><p>Namun, ketika mereka tiba di Pulau Kemaro, mereka kecewa karena hujan deras turun. Pertunjukan barongsai dan penerbangan lampion harus dibatalkan. Adit dan Danu merasa sedih karena tidak bisa melihat semua acara yang telah mereka nantikan. Meskipun begitu, mereka tetap berusaha menikmati perayaan Cap Go Meh dengan berkeliling pulau dan mencoba makanan khas Imlek. Mereka belajar bahwa tidak semua hal bisa berjalan sesuai rencana, dan yang terpenting adalah tetap bersyukur dan menjalani dengan baik apa yang ada.</p>`,src:'Sumber bacaan: detik.com, bisnis.com, antaranews.com, tribunnews.com'},
kota:{img:['b24'],title:'Kota Berkelanjutan',html:`<p>Perubahan iklim, bencana alam, dan kesehatan manusia adalah masalah serius. Untuk mengatasinya, pemerintah berupaya membangun kota berkelanjutan. Kita perlu tahu ciri-ciri kota yang nyaman dan sehat.</p><p>Kota berkelanjutan memiliki transportasi publik ramah lingkungan dan murah. Bus dan kereta tidak mencemari udara serta terjangkau. Kendaraan pribadi juga harus ramah lingkungan, seperti mobil listrik. Kota ini menyediakan jalur khusus untuk pejalan kaki dan pesepeda.</p><p>Listrik di kota berkelanjutan berasal dari tenaga surya. Gedung-gedung dirancang hemat energi dan ramah lingkungan. Penggunaan air pun dilakukan secara bijak dan efisien.</p><p>Fasilitas publik mudah diakses oleh semua orang. Taman, perpustakaan, dan rumah sakit tersedia di berbagai lokasi. Kota juga memiliki ruang terbuka hijau yang nyaman dan asri.</p><p>Kota berkelanjutan memperhatikan produksi makanan ramah lingkungan. Pengelolaan sampah dilakukan dengan baik, termasuk daur ulang sampah.</p><p>Dengan semua ciri-ciri ini, kota menjadi sehat, nyaman, dan ramah lingkungan. Mari jaga kota kita agar tetap berkelanjutan!</p>`,src:'Sumber: kompas.com'},
rara:{img:['b27'],title:'Ruwatan Rara',html:`<div class="dlg"><p>"Pokoknya Rara mau hp sebelum ruwatan!" rengek Rara.</p><p>"Maaf, Nak! Ibu belum bisa membelikannya!" terang Ibu.</p><p>"Jadi Rara tidak bisa ikut tradisi ruwatan?" tanyanya kesal.</p><p>Ibu sedih mendengar pertanyaan Rara. Ayah yang tidak sengaja lewat ikut mendengar.</p><p>"Rara! Kamu minta hp?" tanya Ayah.</p><p>"Iya!" jawabnya. "Kata ketua adat, Rara boleh minta satu permintaan ke ayah ibu," terang Rara. "Terus, permintaan Rara itu harus dipenuhi, baru Rara bisa ikut ruwatan, Yah!" lanjut Rara.</p><p>Ayah mengangguk, dan perlahan menjelaskan keadaan mereka. Ibunya seorang pedagang kecil dan ayah hanya penjaga vila. Jadi cukup berat untuk membelikan hp.</p><p>Rara sadar, dirinya tidak kaya dan meminta maaf ke Ayah dan Ibu. Akhirnya Rara hanya meminta dibelikan buku cerita di pasar.</p><p>Tibalah hari ruwatan, saat rambut Rara akan dipotong. Rara sudah bersiap dengan baju adat.</p><p>"Wuah, bagus bajunya!" kata Rara takjub.</p><p>"Ayo, Nak! Kamu harus segera bergabung dengan teman lainnya!" perintah Ibu.</p><p>"Mau ke mana, Bu?" tanya Rara.</p><p>Ibu menjelaskan kalau Rara akan dibawa ke tempat ritual ruwatan. Di sana ketua adat akan memotong rambut gimbal Rara.</p><p>"Setelah rambut Rara dipotong, Rara ngapain, Bu?"</p><p>"Penyerahan permintaan dan larung rambut!" jawab Ibu, dan Rara menjadi bingung.</p><p>"Ibu dan ayah akan memberikan barang yang kamu minta kemarin," jawab Ibu.</p><p>"Asik! Terima kasih, Bu!" ucap Rara.</p><p>"Tapi kamu harus tetap ikut acara larung rambut, ya, di sungai dekat desa!"</p><p>"Baik, Ibu!" sambil memberikan jempol.</p><p class="src">Daftar istilah: HP = handphone/ponsel. Tradisi ruwatan = tradisi mencukur rambut anak gimbal untuk melepaskan seseorang dari keburukan.</p></div>`},
arul:{img:['b33'],title:'Nilai Arul',html:`<div class="dlg"><p>Nilai Arul selalu bagus sejak dulu. Padahal, dia tidak pernah belajar. Tapi, nilai Arul mulai menurun.</p><p><b>Dewi:</b> "Arul, belajar bareng, yuk! Bareng Reno dan Erni."</p><p><b>Arul:</b> "Enggak mau, ah! Aku malas."</p><p><b>Dewi:</b> "Ya, sudah. Aku belajar bareng dulu, ya."</p><p><b>Arul:</b> "Belajar saja sana. Paling nilainya lebih bagus aku. Mending aku main bola."</p><p>Arul kembali bermain. Dia mengambil sepatunya, berlari ke lapangan sambil membawa bola, dan menendang bola ke gawang yang kosong.</p><p>Keesokan hari setelah ujian, Arul kaget saat melihat nilainya.</p><p><b>Arul:</b> "Kok nilaiku jelek banget?"</p><p><b>Reno:</b> "Emang apa yang kamu pelajari, Rul?"</p><p><b>Arul:</b> "Buat apa aku belajar? Nilaiku loh selalu bagus."</p><p><b>Erni:</b> "Ya, enggak bisa begitu, Arul. Pelajaran kita kan semakin susah."</p><p><b>Dewi:</b> "Iya, kita sudah harus rajin belajar."</p><p><b>Arul:</b> "Dulu aku tidak belajar. Nilaiku juga selalu bagus, 'kan?"</p><p><b>Reno:</b> "Iya. Itu 'kan dulu. Lihat nilaimu sekarang. Semakin lama semakin jelek, 'kan?"</p><p>Arul hanya bisa memandangi nilainya.</p><p><b>Dewi:</b> "Kamu harus belajar kalau mau nilai bagus."</p><p><b>Erni:</b> "Iya. Berakit-rakit ke hulu, berenang-renang kemudian. Bersakit-sakit dahulu, bersenang-senang kemudian."</p><p><b>Dewi:</b> "Betul. Harus berusaha kalau mau berhasil."</p><p><b>Arul:</b> "Apa itu?"</p><p><b>Reno:</b> "Peribahasa, Rul. Ayo belajar bareng biar sama-sama tahu."</p><p>Arul pun mengangguk.</p></div>`},
nelayan:{img:['b39'],title:'Yunus dan Kamal',html:`<p>Sudah bertahun-tahun Yunus bekerja sebagai nelayan. Setiap hari ia mengarungi laut dan melempar jala. Asal tidak badai, Yunus pasti melaut.</p><p>Hal ini sangat berbeda dengan Kamal. Padahal keduanya sama-sama mencari hidup di laut. Tapi, Kamal sering bermalas-malasan.</p><p>Suatu hari, Kamal datang ke rumah Yunus. "Yunus, bolehkah aku minta ikan?" kata Kamal.</p><p>"Lho, kamu tidak dapat ikan?" tanya Yunus. "Padahal lagi musim ikan, lho."</p><p>"Ah, itu. Aku kemarin tidak melaut. Aku sibuk memperbaiki perahuku yang rusak."</p><p>Merasa kasihan, Yunus memberikan beberapa ikan. Yunus juga mengingatkan Kamal untuk segera melaut.</p><p>Beberapa hari berlalu, Kamal masih belum melaut. Alasan Kamal seluas lautan. Tidak ada habisnya. Mulai dari ombak, perahu, sampai anak. Semuanya dijadikan alasan oleh Kamal. Yunus sampai kesal.</p><p>Saat Kamal datang untuk meminta ikan lagi, "Kamal, ayo melaut. Ikut aku kalau perahumu masih rusak," tegas Yunus.</p><p>"Waduh, belum bisa," tolak Kamal.</p><p>"Ikut saja. Aku kesal melihatmu bermalas-malasan setiap hari," kata Yunus. "Orang kampung juga malas denganmu. Setiap hari hanya tiduran, lalu meminta ikan pada tetangga."</p><p>Kamal hanya terdiam. Kamal memang sudah semakin susah meminta ikan. Dengan berat, Kamal melawan rasa malasnya. Ia ikut Yunus melaut. Setiap hari, Kamal ikut dengan Yunus.</p><p>Sekarang Kamal sudah melaut setiap hari. Kamal bahkan melaut dengan perahunya sendiri.</p>`},
lianne:{img:['b43'],title:'Mama, Aku Bukan Dia',html:`<p>Halo! Namaku Lianne. Aku suka sekali menggambar. Ini teman-temanku. Ada Albert, Giffari, dan Amber. Kami sedang bermain bersama.</p><p>Suatu hari, Albert memenangi lomba matematika. Sebagai temannya, aku sangat bangga kepadanya! Namun, saat aku pulang, Mama berkata, "Coba saja kamu pintar seperti Albert! Dia pintar matematika! Dia pasti rajin belajar!"</p><p>Aku tidak boleh mengecewakan Mama. Aku harus bisa seperti Albert. Namun, hasil belajarku semalam suntuk tetap saja tidak berhasil.</p><p>Saat aku jalan bersama Mama, aku bertemu Giffari. Dia sedang bermain basket. Keren sekali. "Coba saja kamu pandai bermain basket seperti Giffari!" seru Mama.</p><p>Aku berlatih basket. Susah sekali ternyata. Aku tidak bisa.</p><p>Saat pulang, aku melihat Amber sedang bernyanyi. Wah, merdu sekali! "Coba saja kamu pandai bernyanyi seperti Amber! Lihat! Bagus sekali, bukan?" seru Mama.</p><p>Aku mencoba menyanyi. "Bukan begitu!!! Nada kamu salah!!!" teriak Amber.</p><p>Uuuh! Aku kesal sekali. Lebih baik aku menggambar saja. Sebaiknya, aku melatih kemampuan menggambarku di luar. Bertemu dengan orang-orang. Berkeliling tempat berbeda. Mencari ide menarik. Menyenangkan sekali!</p><p>Wah, ada lomba menggambar! Aku pun mengirimkan gambarku. Beberapa hari kemudian, tiba-tiba Mama memberitahuku. Katanya, aku menang lomba menggambar! Mama bangga sekali denganku. Mama sadar bahwa setiap anak memiliki kelebihan masing-masing. Aku senang akhirnya Mama menerima bakatku apa adanya.</p>`,src:'Sumber: budi.kemdikbud.id'}
},qs:[
{t:'pg',p:'mangrove',q:'Bagan manakah yang sesuai untuk menggambarkan hutan mangrove pada teks?',
 opts:['<b>HUTAN MANGROVE</b> → Lokasi: Kulon Progo · Zona Menarik: Ayunan · Contoh Satwa: Kepiting','<b>HUTAN MANGROVE</b> → Lokasi: Dekat Pantai Congot · Zona Menarik: Jembatan Api-Api · Contoh Satwa: Udang','<b>HUTAN MANGROVE</b> → Lokasi: Kulon Progo · Zona Menarik: Menara Pandang · Contoh Satwa: Biawak','<b>HUTAN MANGROVE</b> → Lokasi: Dekat Pantai Congot · Zona Menarik: Gazebo · Contoh Satwa: Burung Kuntul'],ans:1,
 exp:`<p>Kuncinya ada di kotak <b>Zona Menarik</b>. Teks menyebut zona menarik hanya tiga: <i>Pasir Mendit, Jembatan Api-Api, dan Pantai Kadilangu</i>. Ayunan, menara pandang, dan gazebo disebut sebagai <b>spot foto</b>, bukan zona.</p><p>Hanya bagan B yang zonanya benar (Jembatan Api-Api). Lokasinya juga sesuai (dekat Pantai Congot), dan udang memang termasuk satwa yang disebut dalam teks.</p>`},
{t:'mcma',p:'mangrove',q:'Apa maksud istilah “permata tersembunyi” dalam teks?',opts:['Letak yang tidak mudah dijangkau, tetapi ramai dikunjungi.','Tempat yang indah, tetapi belum dikenal banyak orang.','Lokasi yang jarang diketahui, tetapi memiliki banyak spot menarik.'],ans:[1,2],
 exp:`<p><b>Permata</b> = sesuatu yang indah dan berharga. <b>Tersembunyi</b> = belum banyak diketahui orang. Dalam teks, istilah ini muncul setelah penjelasan banyaknya spot foto menarik (“Tak heran jika tempat ini disebut…”).</p><ul><li>A salah: “ramai dikunjungi” bertentangan dengan makna “tersembunyi”, dan teks tidak menyebut tempatnya sulit dijangkau.</li><li>B benar: indah, tetapi belum dikenal banyak orang.</li><li>C benar: jarang diketahui, tetapi punya banyak spot menarik, sesuai kalimat sebelum istilah itu.</li></ul>`},
{t:'kat',p:'mangrove',ctx:`<div class="dlg"><p><b>Amara:</b> “Menurutku, judul <i>Indahnya Hutan-Hutan Mangrove di Indonesia</i> kurang tepat. Teksnya hanya fokus membahas hutan mangrove di Kulon Progo, bukan seluruh Indonesia.”</p><p><b>Bima:</b> “Setuju. Kalau mau pakai judul itu, isi teks seharusnya membahas beberapa hutan mangrove di daerah lain juga. Bukan satu tempat saja.”</p><p><b>Jena:</b> “Tapi, judul itu menurutku masih cocok, kok. Soalnya, Hutan Kulon Progo juga bagian dari hutan-hutan mangrove di Indonesia. Jadi, tetap mewakili.”</p></div>`,
 q:'Pendapat siapa yang tepat dalam menggambarkan kesesuaian judul dengan isi teks tersebut?',cols:BS,
 rows:['Amara karena isi teks hanya fokus membahas Hutan Mangrove Kulon Progo.','Bima karena judul lebih cocok jika membahas beberapa hutan mangrove lain juga.','Jena karena Hutan Kulon Progo dapat mewakili seluruh hutan mangrove di Indonesia.'],ans:[0,0,1],
 exp:`<p>Judul memakai kata <b>“Hutan-Hutan”</b> (jamak) dan <b>“di Indonesia”</b> (luas), padahal seluruh isi teks hanya membahas satu tempat, yaitu Hutan Mangrove Kulon Progo.</p><ul><li>Amara – <b>Benar</b>: ia menunjukkan ketidaksesuaian judul dengan isi.</li><li>Bima – <b>Benar</b>: judul jamak cocok jika isi membahas beberapa hutan mangrove.</li><li>Jena – <b>Salah</b>: satu tempat tidak bisa mewakili seluruh hutan mangrove Indonesia yang berbeda-beda.</li></ul>`},
{t:'mcma',p:'bakwan',q:'Mengapa bakwan dikatakan sebagai makanan yang unik?',opts:['Memiliki isi yang sama dengan makanan Jepang.','Perkembangannya dipengaruhi budaya negara lain.','Ditemukan di berbagai daerah dengan sebutan berbeda.'],ans:[1,2],
 exp:`<ul><li>A salah: teks hanya menyebut tempura <i>bisa jadi ikut memengaruhi</i>, bukan isinya sama.</li><li>B benar: paragraf 1 menyebut bakwan muncul karena pengaruh budaya Cina, Jepang, dan Eropa (Portugis).</li><li>C benar: paragraf 4 menyebut namanya berbeda di tiap daerah (ote-ote, weci, bala-bala, badak).</li></ul>`},
{t:'kat',p:'bakwan',q:'Apa perbedaan bakwan sebelum dan sesudah terpengaruh budaya Jepang?',cols:['Sebelum','Sesudah'],rows:['Berisi aneka sayuran.','Isi hanya daging.','Isinya ditambahkan udang.'],ans:[1,0,1],
 exp:`<ul><li><b>Sebelum:</b> “Awalnya, bakwan terbuat dari daging dan tepung yang digoreng” → isi hanya daging.</li><li><b>Sesudah</b> (pengaruh tempura, sayur digoreng tepung): “Kini, bakwan berisi aneka sayuran… Bisa juga ditambahkan isian udang, sosis, atau bakso.”</li></ul>`},
{t:'mcma',p:'biru',q:'Nilai moral apa saja yang diperoleh dari cerita tersebut?',opts:['Bebas memilih gaya hidup.','Peduli lingkungan itu penting.','Hal kecil bisa jadi langkah baik.'],ans:[1,2],
 exp:`<ul><li>A salah: cerita justru mengajak Alvin mengubah kebiasaan beli-buang, bukan membenarkan “bebas memilih”.</li><li>B benar: “Kita harus peduli” terhadap sampah plastik.</li><li>C benar: “Mulai dari hal kecil, seperti bawa botol sendiri.”</li></ul>`},
{t:'pg',p:'biru',q:'Makna ungkapan <i>tutup mata</i> berdasarkan dialog yang diucapkan Salma dalam wacana tersebut adalah ....',opts:['mengabaikan masalah sampah di sekitar','melupakan berbagai isu lingkungan','menumpuk plastik-plastik sisa pakai','meningkatkan kasus pencemaran tanah'],ans:0,
 exp:`<p>Ungkapan <b>tutup mata</b> berarti pura-pura tidak melihat, yaitu <b>tidak peduli atau mengabaikan</b>. Kalimat Salma: “Kita nggak bisa terus <i>tutup mata</i> soal sampah plastik. Kita harus peduli.” Jadi maknanya mengabaikan masalah sampah di sekitar. “Melupakan” berbeda dengan “mengabaikan”, dan pilihan C–D bukan arti ungkapan.</p>`},
{t:'kat',p:'biru',q:'Rania telah membaca cerita <i>Si Biru Kesayangan</i>. Ia tersadar untuk memulai aksi peduli lingkungan seperti Alvin. Apa yang sebaiknya Rania lakukan untuk memulai aksinya berdasarkan cerita tersebut?',cols:['Sesuai','Tidak Sesuai'],
 rows:['Menggunakan botol minum isi ulang setiap hari.','Membeli botol minum isi ulang untuk teman-temannya.','Mengajak teman-teman membatasi pembelian minuman kemasan.'],ans:[0,1,0],
 exp:`<ul><li><b>Sesuai:</b> membawa botol sendiri setiap hari, seperti Salma dengan Si Biru (“nggak pernah beli minuman kemasan lagi”).</li><li><b>Tidak sesuai:</b> membelikan botol untuk teman tidak ada dalam cerita. Salma dan Siva hanya <i>membantu mencari</i> botol bersama Alvin.</li><li><b>Sesuai:</b> mengajak teman mengurangi minuman kemasan, seperti cara Salma dan Siva mengajak Alvin.</li></ul>`},
{t:'pg',p:'meteor',q:'Mengapa hujan meteor tidak berbahaya?',opts:['Meteor dapat berpindah.','Hanya muncul saat langit cerah.','Hanya muncul saat hujan.','Akan habis terbakar di langit.'],ans:3,
 exp:`<p>Informasi tersurat di paragraf 3: “Hujan meteor tidak berbahaya, kok. Jangan takut, meteor ini <b>akan habis terbakar di langit</b>.”</p>`},
{t:'mcma',p:'meteor',q:'Berdasarkan cerita di atas, hal apa saja yang dapat membuat tokoh “Aku” senang?',opts:['Menonton hujan meteor dengan ayahnya.','Menulis buku harian sambil melihat meteor.','Langit cerah ketika menonton hujan meteor.'],ans:[0,2],
 exp:`<ul><li>A benar: “Aku senang sekali menghabiskan waktu dengan ayah!”</li><li>B salah: buku harian ditulis sebelum menonton, bukan sambil melihat meteor.</li><li>C benar: ia berdoa agar tidak hujan karena meteor tampak lebih jelas jika langit cerah. Langit cerah adalah yang ia harapkan.</li></ul>`},
{t:'pg',p:'giga',q:'Bentuk apa yang bisa ditiru Giga saat bermain dengan Heksagonal?',opts:['Bunga.','Pohon cemara.','Gunung.','Atap rumah.'],ans:0,
 exp:`<p>Tersurat: “Saat bermain dengan Heksagonal, dia menirukan bentuk <b>bunga</b>.” Pohon cemara, gunung, dan atap rumah adalah bentuk yang ditiru Giga bersama teman segitiganya.</p>`},
{t:'mcma',p:'giga',q:'Apa yang dibuat Giga saat bermain bersama Pasukan Kotak?',opts:['Roket.','Menara.','Bendera.'],ans:[0,1],
 exp:`<p>Tersurat: “Giga juga suka bermain dengan Pasukan Kotak. Banyak bentuk yang bisa ditirukan, seperti <b>roket, ikan, dan menara</b>.” Bendera termasuk contoh bentuk sesama segitiga.</p>`},
{t:'pg',p:'capgomeh',q:'Bagaimana cara keluarga Adit dan Danu pergi ke Pulau Kemaro saat pertama kalinya?',opts:['Menyeberangi jembatan ponton dengan mobil.','Melewati jembatan ponton dengan berjalan kaki.','Menggunakan kapal dari bawah jembatan Musi.','Melewati jembatan Musi dengan berjalan kaki.'],ans:2,
 exp:`<p>“Ini adalah <b>kedua kalinya</b>… <b>Waktu itu</b> (kali pertama), mereka <b>naik kapal dari bawah jembatan Musi</b>.” Berjalan kaki lewat jembatan ponton adalah cara pada kunjungan kedua. Hati-hati dengan kata penunjuk waktu.</p>`},
{t:'mcma',p:'capgomeh',q:'Apa peristiwa yang membuat Danu dan Adit berpikir bahwa bersyukur adalah hal yang penting di dalam hidup mereka?',opts:['Pertunjukan barongsai ditiadakan sehingga mereka memilih berkeliling pulau.','Keluarga Danu berjalan kaki melewati jembatan ponton meskipun hujan turun.','Penerbangan lampion dihilangkan, mereka memilih makan makanan khas Imlek.'],ans:[0,2],
 exp:`<p>Pelajaran bersyukur muncul ketika acara batal karena hujan, tetapi mereka tetap menikmati apa yang ada: <b>berkeliling pulau</b> dan <b>mencoba makanan khas Imlek</b>. Pilihan B tidak ada di teks. Hujan turun ketika mereka sudah tiba di pulau, bukan saat berjalan di jembatan.</p>`},
{t:'pg',p:'capgomeh',q:'Berdasarkan cerita, apa yang akan kamu lakukan jika rencana berlibur ke pantai batal akibat hujan?',opts:['Berlapang dada dan memilih untuk menyusun rencana menyenangkan lain di rumah.','Merasa sedih sehingga memilih untuk melihat hujan dari jendela berharap hujan segera reda.','Bersikap biasa-biasa saja dan memilih untuk berdiam diri di rumah tanpa aktivitas apa pun.','Memilih untuk melanjutkan tidur sembari berharap hujan bisa reda ketika sudah bangun nantinya.'],ans:0,
 exp:`<p>Amanat cerita: tidak semua hal berjalan sesuai rencana, yang penting tetap bersyukur dan <b>menjalani dengan baik apa yang ada</b>. Sikap yang sejalan: menerima dengan lapang dada lalu mencari kegiatan menyenangkan lain, seperti Adit dan Danu yang berkeliling pulau. Pilihan lain hanya pasif atau berlarut sedih.</p>`},
{t:'pg',p:'kota',q:'Apa yang menjadi fokus utama dalam teks tersebut?',opts:['Manfaat menggunakan kendaraan tenaga listrik.','Pentingnya kota berkelanjutan untuk masa depan.','Fasilitas publik yang tersedia di kota berkelanjutan.','Cara pengolahan sampah di kota berkelanjutan.'],ans:1,
 exp:`<p>Seluruh teks membahas kota berkelanjutan: alasannya (mengatasi perubahan iklim, bencana, kesehatan), ciri-cirinya, dan ajakan menjaganya. Pilihan A, C, dan D hanya bagian kecil (gagasan pendukung) dari teks.</p>`},
{t:'pg',p:'kota',q:'Hasil apa yang diharapkan dari sistem pengolahan sampah yang baik?',opts:['Kota menjadi bersih.','Air menjadi melimpah.','Udara menjadi sejuk.','Waktu menjadi efisien.'],ans:0,
 exp:`<p>Pengelolaan sampah yang baik (termasuk daur ulang) membuat kota tidak dipenuhi sampah, sehingga <b>kota menjadi bersih</b> dan sehat. Air melimpah dan udara sejuk berkaitan dengan hal lain di teks (penggunaan air yang bijak, transportasi ramah lingkungan).</p>`},
{t:'mcma',p:'kota',q:'Berdasarkan isi teks, mengapa ciri-ciri kota berkelanjutan belum nampak dalam gambar?',opts:['Tidak ada gambar ruang terbuka hijau seperti taman dan lapangan.','Tidak ada gambar alat transportasi ramah lingkungan bertenaga listrik.','Tidak ada gambar manusia yang sedang melakukan aktivitas di jalan.'],ans:[0,1],
 exp:`<p>Bandingkan gambar dengan ciri-ciri dalam teks. Gambar hanya berisi gedung, beberapa pohon pinggir jalan, dan zebra cross.</p><ul><li>A benar: teks menyebut taman dan ruang terbuka hijau, tetapi di gambar tidak ada taman atau lapangan.</li><li>B benar: teks menyebut bus, kereta, dan mobil listrik, tetapi di gambar tidak ada kendaraan sama sekali.</li><li>C salah: “manusia beraktivitas” bukan ciri kota berkelanjutan menurut teks.</li></ul>`},
{t:'pg',p:'rara',q:'Siapa yang memotong rambut Rara saat ruwatan?',opts:['Ketua adat','Ibu Rara','Ayah Rara','Tukang cukur'],ans:0,
 exp:`<p>Tersurat: “Di sana <b>ketua adat</b> akan memotong rambut gimbal Rara.”</p>`},
{t:'pg',p:'rara',q:'Bagaimana perasaan Rara setelah mendengar penjelasan Ayah?',opts:['Lega.','Puas.','Ceria.','Ikhlas.'],ans:3,
 exp:`<p>Setelah Ayah menjelaskan keadaan keluarga, Rara sadar, meminta maaf, lalu <b>mengganti permintaannya</b> menjadi buku cerita saja. Menerima keadaan dengan rela disebut <b>ikhlas</b>. Ia belum lega, puas, atau ceria karena keinginannya untuk punya hp tidak terpenuhi.</p>`},
{t:'mcma',p:'rara',q:'Sebelumnya kamu suka memaksa minta barang yang kamu inginkan kepada orang tua. Setelah membaca cerita tersebut, apa yang sebaiknya kamu lakukan jika suatu hari kamu ingin punya barang baru?',opts:['Bertanya kepada ayah dan ibu apakah punya uang atau tidak.','Meminta ayah dan ibu langsung membelikan barang itu.','Memikirkan apakah barang itu perlu atau tidak dimiliki saat ini.'],ans:[0,2],
 exp:`<p>Pelajaran dari Rara: memahami <b>kemampuan orang tua</b> dan tidak memaksa.</p><ul><li>A benar: menanyakan kondisi keuangan berarti memahami keadaan orang tua, seperti Rara setelah mendengar penjelasan Ayah.</li><li>B salah: meminta langsung dibelikan sama dengan sikap memaksa Rara di awal cerita.</li><li>C benar: menimbang kebutuhan, seperti Rara yang akhirnya memilih buku cerita.</li></ul>`},
{t:'pg',p:'arul',q:'Dalam cerita tersebut, Erni mengatakan “bersakit-sakit dahulu, bersenang-senang kemudian”. Apa maksud Erni saat mengatakan itu?',opts:['Menginformasikan kepada Arul bahwa ia harus lebih giat dan semangat lagi dalam belajar.','Memperjelas ucapan Erni bahwa Arul bisa mendapatkan nilai bagus kalau belajar bersama.','Menasihati Arul bahwa ia bisa mendapatkan nilai yang bagus kalau dia tidak sombong.','Memberitahukan kepada Arul bahwa ia harus mau belajar kalau ingin nilai ujiannya bagus lagi.'],ans:3,
 exp:`<p>Peribahasa itu berarti harus <b>bersusah payah (berusaha) dahulu</b> agar kemudian <b>berhasil</b>. Erni mengatakannya untuk menguatkan ucapan Dewi “Kamu harus belajar kalau mau nilai bagus.” Jadi maksudnya: Arul harus mau belajar agar nilainya bagus lagi.</p><p>A kurang tepat karena Arul selama ini tidak belajar sama sekali, jadi bukan soal “lebih giat lagi”. B dan C tidak sesuai makna peribahasa.</p>`},
{t:'pg',p:'arul',q:'Bagaimana perubahan sikap Arul setelah menyadari nilainya jelek?',opts:['Arul menjadi lebih giat untuk belajar sendiri di rumah.','Arul berjanji belajar lebih giat kepada teman-temannya.','Arul akhirnya mau belajar bersama teman-temannya.','Arul merasa akan lebih mudah dalam ujian jika dia belajar.'],ans:2,
 exp:`<p>Di awal Arul menolak ajakan belajar bareng (“Enggak mau, ah! Aku malas.”). Di akhir, ketika Reno mengajak “Ayo belajar bareng”, <b>Arul pun mengangguk</b>. Jadi ia berubah menjadi mau belajar bersama teman-temannya. Pilihan lain tidak tertulis di cerita.</p>`},
{t:'kat',p:'arul',q:'Setelah membaca cerita tersebut, Riza merasa memiliki kesamaan dengan Arul yang nilainya semakin memburuk. Apa yang bisa dilakukan Riza agar nilainya bisa bagus berdasarkan pengalaman cerita Arul?',cols:BS,
 rows:['Belajar kelompok bersama teman-teman agar ada yang mengajari materi sulit.','Meyakini kemampuan diri dan tetap menjalankan hobi bermain sepak bola di lapangan.','Bertanya ketika guru menjelaskan pelajaran agar lebih yakin menjawab pertanyaan saat ujian.'],ans:[0,1,0],
 exp:`<ul><li><b>Benar</b>: belajar kelompok adalah solusi dalam cerita (“Ayo belajar bareng”).</li><li><b>Salah</b>: terlalu yakin pada diri sendiri lalu memilih main bola justru penyebab nilai Arul turun.</li><li><b>Benar</b>: bertanya ketika guru menjelaskan termasuk usaha belajar, sesuai pesan “harus berusaha kalau mau berhasil”.</li></ul>`},
{t:'pg',p:'nelayan',q:'Bagaimana sikap Kamal setelah ia mendapat teguran dan dipaksa ikut melaut dengan Yunus?',opts:['Tersadar untuk rajin melaut setiap hari.','Bersemangat melaut bersama para warga.','Tergerak untuk serius memperbaiki kapal.','Berusaha keras membuktikan pada warga.'],ans:0,
 exp:`<p>Akhir cerita: Kamal melawan rasa malasnya, ikut Yunus setiap hari, dan “Sekarang Kamal sudah <b>melaut setiap hari</b>. Kamal bahkan melaut dengan perahunya sendiri.” Teks tidak menyebut ia melaut bersama warga, fokus memperbaiki kapal, atau ingin membuktikan diri.</p>`},
{t:'kat',p:'nelayan',ctx:`<div class="dlg"><p>Setelah membaca cerita, Johan, Simon, dan Maria berpendapat:</p><p><b>Simon:</b> “Aku kagum dengan sikap Yunus yang tetap mau menemani Kamal.”</p><p><b>Johan:</b> “Iya, tapi Yunus terlalu sabar dengan perilaku Kamal. Itu menjengkelkan.”</p><p><b>Maria:</b> “Aku pun geregetan karena Kamal memang pantas ditegur dengan keras.”</p></div>`,
 q:'Pendapat siapa yang paling sesuai dengan bagian akhir cerita tersebut?',cols:['Sesuai','Tidak Sesuai'],
 rows:['Johan karena Yunus memang terlalu baik hati pada Kamal dan tetangga.','Simon karena Yunus mau menemani Kamal sampai terbiasa melaut sendiri.','Maria karena Yunus menegur keras ketika perilaku Kamal sudah kelewatan.'],ans:[1,0,0],
 exp:`<p>Bagian akhir cerita: Yunus <b>menegur dengan tegas</b> (“Aku kesal melihatmu bermalas-malasan…”), lalu <b>mengajak Kamal melaut setiap hari</b> sampai Kamal bisa melaut dengan perahunya sendiri.</p><ul><li>Johan – <b>Tidak sesuai</b>: di akhir cerita Yunus justru tidak lagi “terlalu sabar”. Ia menegur keras, dan cerita tidak membahas kebaikan Yunus pada tetangga.</li><li>Simon – <b>Sesuai</b>: Yunus menemani Kamal sampai terbiasa.</li><li>Maria – <b>Sesuai</b>: Yunus menegur keras ketika alasan Kamal sudah tak ada habisnya.</li></ul>`},
{t:'pg',p:'lianne',q:'Siapa yang sangat suka menggambar?',opts:['Albert.','Giffari.','Lianne.','Amber.'],ans:2,
 exp:`<p>Kalimat pembuka: “Halo! Namaku <b>Lianne</b>. Aku suka sekali menggambar.” Albert pandai matematika, Giffari bermain basket, dan Amber bernyanyi.</p>`},
{t:'pg',p:'lianne',q:'Bagaimana sifat yang ditunjukkan Lianne pada cerita tersebut?',opts:['Rajin belajar, dibuktikan dengan ia yang berprestasi pada pelajaran matematika.','Gemar olahraga, dibuktikan dengan ia yang rajin berlatih olahraga basket.','Pantang menyerah, dibuktikan dengan ia yang terus giat mengasah bakatnya.','Lapang dada, dibuktikan dengan ia yang dapat menerima kekurangan dirinya.'],ans:2,
 exp:`<p>Lianne terus mencoba, lalu memutuskan <b>melatih kemampuan menggambarnya</b> (berkeliling, mencari ide), ikut lomba, dan menang. Itu sifat <b>pantang menyerah</b> mengasah bakat.</p><p>A dan B tidak sesuai: matematikanya tidak berhasil dan basketnya tidak bisa. D kurang tepat: ia justru kesal, dan fokus cerita ada pada usahanya mengembangkan bakat.</p>`},
{t:'kat',p:'lianne',q:'Dinda selesai membaca cerita “Mama, Aku Bukan Dia”. Dinda juga tidak suka dibanding-bandingkan dengan orang lain. Ia yakin setiap orang memiliki keunggulan yang berbeda-beda. Apa kemungkinan yang dirasakan oleh Dinda ketika Lianne selalu dibandingkan dengan teman-temannya oleh mamanya?',cols:['Setuju','Tidak Setuju'],
 rows:['Sedih, karena Lianne selalu tidak diakui keunikannya oleh mamanya.','Marah, karena teman-temannya selalu lebih unggul darinya.','Kecewa, karena ia tidak bisa menjadi dirinya sendiri di depan mamanya.'],ans:[0,1,0],
 exp:`<p>Dinda percaya <b>setiap orang punya keunggulan berbeda</b>, jadi ia akan berempati pada Lianne yang kelebihannya (menggambar) tidak dihargai.</p><ul><li><b>Setuju</b>: sedih karena keunikan Lianne tidak diakui.</li><li><b>Tidak setuju</b>: marah karena teman lebih unggul bertentangan dengan keyakinan Dinda. Teman-teman tidak “selalu lebih unggul”, hanya unggul di bidangnya masing-masing.</li><li><b>Setuju</b>: kecewa karena Lianne dipaksa menjadi seperti orang lain, bukan dirinya sendiri.</li></ul>`}
]};
